package com.bridge.quartercore;
import org.junit.jupiter.api.Test;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class FixedECompiledBaselineTest {
 @Test void actualReviewedProjectionPinnedAndUnmodified(){var b=FixedECompiledBaseline.snapshot();assertEquals(FixedERestartPreflight.INITIAL_TOKEN,JournalSessionAuthority.fullToken(b));var bundle=FixedEBaselineBundle.compiled();assertEquals(0,bundle.completedPairs(b));bundle.requireNextClaim(b);assertEquals(NativeRestartCompiledRelease.pendingReview().binding(),NativeRestartCompiledRelease.require().binding());assertEquals(FixedERestartClock.binding(),FixedEBoundedRestartMain.contract().binding());}
 @Test void completedArtifactRequiresAtLeastOnePairAndStopsAfterThree(){var base=FixedECompiledBaseline.snapshot();var empty=FixedEVerifiedArtifact.completedRestart();assertThrows(RuntimeException.class,()->empty.verifyOnce(()->base));assertNull(empty.response("GET",FixedEVerifiedArtifact.PATH,null));var one=FixedERestartHttpSafetyTest.pair(base,"w-"+UUID.randomUUID());var ready=FixedEVerifiedArtifact.completedRestart();ready.verifyOnce(()->one);assertNotNull(ready.response("GET",FixedEVerifiedArtifact.PATH,null));assertNull(ready.response("GET",FixedEVerifiedArtifact.PATH,""));}
 @Test void artifactChangeRejectedBeforeParsing()throws Exception{try(var in=getClass().getResourceAsStream(FixedECompiledBaseline.RESOURCE)){byte[] bytes=in.readAllBytes();bytes[bytes.length/2]^=1;assertThrows(RuntimeException.class,()->FixedECompiledBaseline.decode(bytes));}}
 @Test void explicitOptInAndNoOverrides(){assertThrows(RuntimeException.class,()->FixedEBoundedRestartMain.requireConfiguration(Map.of()));var e=new HashMap<String,String>();e.put("BRIDGE_FIXED_E_BOUNDED_RESTART_ENABLED","true");assertThrows(RuntimeException.class,()->FixedEBoundedRestartMain.requireConfiguration(e));e.put("BRIDGE_READONLY_STARTUP_ENABLED","false");e.put("BRIDGE_SHEETS_SPREADSHEET_ID","formal-unused");e.put("BRIDGE_DATASET_ID","formal-unused");assertDoesNotThrow(()->FixedEBoundedRestartMain.requireConfiguration(e));e.put("BRIDGE_FIXED_E_BASELINE","uploaded");assertThrows(RuntimeException.class,()->FixedEBoundedRestartMain.requireConfiguration(e));}
}
